    'decision.PH_LOW.title': '{zone} மண் அதிக அமிலத்தன்மை கொண்டது', 'decision.PH_LOW.detail': 'pH {ph}; {crop}-க்கான வரம்பு {min}–{max}. லேசான சுண்ணாம்பு பயன்பாட்டைக் கருத்தில் கொண்டு 2 வாரங்களில் மீண்டும் சோதிக்கவும்.',
    'decision.PH_HIGH.title': '{zone} மண் அதிக காரத்தன்மை கொண்டது', 'decision.PH_HIGH.detail': 'pH {ph}; {crop}-க்கான வரம்பு {min}–{max}. கரிமப் பொருள் அல்லது கந்தகத்தைச் சேர்த்து மீண்டும் சோதிக்கவும்.',
    'decision.HEAT_STRESS.title': '{zone}-இல் வெப்ப அழுத்த ஆபத்து', 'decision.HEAT_STRESS.detail': 'காற்று வெப்பநிலை {airTemp}°C, இது {max}°C-ஐ விட அதிகம். அதிகாலை அல்லது மாலையில் நீர்ப்பாசனம் செய்து முடிந்தால் நிழல் வழங்கவும்.',
    'decision.COLD_STRESS.title': '{zone}-இல் குறைந்த வெப்பநிலை', 'decision.COLD_STRESS.detail': 'காற்று வெப்பநிலை {airTemp}°C, இது {crop}-க்கு ஏற்ற {min}°C-ஐ விடக் குறைவு. வெப்பமாகும் வரை நீர்ப்பாசனத்தைத் தாமதப்படுத்தவும்.',
    'decision.DISEASE_RISK.title': '{zone}-இல் பூஞ்சை நோய் ஆபத்து', 'decision.DISEASE_RISK.detail': 'ஈரப்பதம் {humidity}% மற்றும் வெப்பமான காற்று ({airTemp}°C). இலைகளில் புள்ளிகளைக் கவனித்து காற்றோட்டத்தை மேம்படுத்தவும்.',
    'decision.RAIN_EVENT.title': '{zone}-இல் மழை நிகழ்வு', 'decision.RAIN_EVENT.detail': 'சமீபத்திய அளவீட்டில் {rainfall} mm பதிவாகியுள்ளது. நிலுவையில் உள்ள நீர்ப்பாசனம் தானாகவே ரத்து செய்யப்படும்.',
    'decision.DATA_QUALITY.title': '{zone}-க்கான தரவுத் தர எச்சரிக்கை', 'decision.DATA_QUALITY.detail': 'கடந்த மணி நேரத்தில் {ratio}% அளவீடுகள் சரிபார்ப்பில் தோல்வியடைந்தன. சென்சார் வயரிங் மற்றும் அளவுத்திருத்தத்தைச் சரிபார்க்கவும்.',
    'decision.STALE_DATA.title': '{zone}-இல் பழைய அளவீடுகள்', 'decision.STALE_DATA.detail': 'கடைசி சரியான அளவீடு {minutes} நிமிடங்கள் பழையது. பரிந்துரைகள் காலாவதியாக இருக்கலாம்.',
    'decision.SENSOR_OFFLINE.title': 'சென்சார் நோடு {node} இணைப்பில் இல்லை', 'decision.SENSOR_OFFLINE.detail': '{minutes} நிமிடங்களாக பாக்கெட்டுகள் இல்லை. மின்சாரம், Wi‑Fi/LoRa இணைப்பு மற்றும் சாதன விசையைச் சரிபார்க்கவும்.',
    'decision.NO_DATA.title': '{zone}-க்கு இன்னும் அளவீடுகள் இல்லை', 'decision.NO_DATA.detail': 'முடிவு ஆதரவைத் தொடங்க சென்சார் நோடை இணைக்கவும் அல்லது உருவகப்படுத்தலை இயக்கவும்.',
    'decision.HEALTHY.title': '{crop} மண்டலம் {zone} கொள்கைக்குள் உள்ளது', 'decision.HEALTHY.detail': 'ஈரப்பதம், pH மற்றும் ஊட்டச்சத்துகள் பயிர் கொள்கை வரம்புகளுக்குள் உள்ளன. இப்போது தானியக்கம் தேவையில்லை.',
    'agent.title': 'காரணங்களுடன் தெளிவான நடவடிக்கைகள்', 'agent.text': 'முகவர் சரிபார்க்கப்பட்ட சென்சார் தரவுகளுக்கு வெளிப்படையான பயிர் கொள்கைகளைப் பயன்படுத்துகிறார். ஒவ்வொரு பரிந்துரையும் அதன் பின்னணியில் உள்ள சான்று மற்றும் விதியைக் காட்டுகிறது. முடிவுகளை உங்கள் வேளாண் நிபுணருடன் உறுதிப்படுத்தவும்.', 'agent.explainable': 'விளக்கக்கூடிய AI', 'agent.autonomous': 'தன்னாட்சி முறை', 'agent.why': 'இது ஏன் பரிந்துரைக்கப்பட்டது?', 'agent.rule': 'விதி', 'agent.policy': 'கொள்கை', 'agent.confidence': 'நம்பகத்தன்மை', 'agent.openWorkflows': 'பணிப்பாய்வு வரிசை', 'agent.historyEyebrow': 'வரலாறு', 'agent.recentWorkflows': 'சமீபத்திய பணிப்பாய்வுகள்',
