    'eval.scenarioEyebrow': 'AI முடிவு ஆதரவு', 'eval.scenarioTitle': 'சூழ்நிலைச் சோதனை முடிவுகள்', 'eval.scenarioRan': 'கடைசி இயக்கம் {when}', 'eval.expected': 'எதிர்பார்க்கப்பட்டது', 'eval.actual': 'முகவர் வெளியீடு', 'eval.pass': 'உடன்பாடு', 'eval.fail': 'மாறுபாடு', 'eval.expertNote': 'எதிர்பார்க்கப்பட்ட முடிவு குறியிடப்பட்ட விதியால் அல்ல, நிபுணர் தீர்ப்பால் நிர்ணயிக்கப்பட்டது; எனவே உடன்பாடு அனுமானிக்கப்படாமல் அளவிடப்படுகிறது.', 'eval.noRun': 'சூழ்நிலைச் சோதனை இன்னும் இயக்கப்படவில்லை', 'eval.noRunText': 'முகவர் உடன்பாட்டை அளவிட 15 முன்வரையறுக்கப்பட்ட சூழ்நிலைகளை இயக்கவும்.',
    'eval.susEyebrow': 'வலைப் பயன்பாட்டினை', 'eval.susTitle': 'கணினிப் பயன்பாட்டினை அளவுகோல் கேள்வித்தாள்', 'eval.susText': 'பத்து நிலையான SUS கூற்றுகள். பதில்கள் அநாமதேயமாக்கப்பட்டு பயன்பாட்டினை அளவீட்டில் சராசரியாக்கப்படுகின்றன.', 'eval.susCount': '{n} பதில்கள்', 'eval.comment': 'கருத்துகள் (விருப்பத்தேர்வு)', 'eval.submitSus': 'கேள்வித்தாளைச் சமர்ப்பி',
    'sus.q1': 'இந்த அமைப்பை அடிக்கடி பயன்படுத்த விரும்புவேன் என நினைக்கிறேன்.', 'sus.q2': 'இந்த அமைப்பு தேவையற்ற அளவு சிக்கலானதாக இருந்தது.', 'sus.q3': 'இந்த அமைப்பு பயன்படுத்த எளிதாக இருந்தது.', 'sus.q4': 'இந்த அமைப்பைப் பயன்படுத்த தொழில்நுட்ப நபரின் உதவி தேவை என நினைக்கிறேன்.', 'sus.q5': 'இந்த அமைப்பின் பல்வேறு செயல்பாடுகள் நன்கு ஒருங்கிணைக்கப்பட்டிருந்தன.', 'sus.q6': 'இந்த அமைப்பில் அதிக முரண்பாடுகள் இருந்தன என நினைத்தேன்.', 'sus.q7': 'பெரும்பாலானோர் இந்த அமைப்பை மிக விரைவாகப் பயன்படுத்தக் கற்றுக்கொள்வார்கள் என நினைக்கிறேன்.', 'sus.q8': 'இந்த அமைப்பு பயன்படுத்த மிகவும் சிரமமாக இருந்தது.', 'sus.q9': 'இந்த அமைப்பைப் பயன்படுத்துவதில் மிகுந்த நம்பிக்கையுடன் இருந்தேன்.', 'sus.q10': 'இந்த அமைப்பைப் பயன்படுத்தத் தொடங்கும் முன் நிறைய கற்றுக்கொள்ள வேண்டியிருந்தது.', 'sus.disagree': 'முற்றிலும் உடன்படவில்லை', 'sus.agree': 'முற்றிலும் உடன்படுகிறேன்',
    'eval.dsrmEyebrow': 'ஆய்வு முறை', 'eval.dsrmTitle': 'Design Science Research சுழற்சி', 'eval.dsrmText': 'இலக்கிற்குக் கீழே உள்ள அளவீடுகள் மீண்டும் பரிசீலிக்க வேண்டிய வடிவமைப்புக் கூறைக் காட்டுகின்றன: சென்சார் அளவுத்திருத்தம் அல்லது இணைப்பு (சென்சார் ஒருங்கிணைப்பு, தரவுத் தரம்), முடிவு விதிகள் (AI முடிவு ஆதரவு), பணிப்பாய்வு தர்க்கம் (தானியக்கம்), இடைமுகம் (பயன்பாட்டினை) அல்லது வணிக ஓட்டம் (B2B) — அடுத்த செயல்விளக்கம் மற்றும் மதிப்பீட்டுச் சுழற்சிக்கு முன்.',
    'settings.title': 'அமைப்புகள்', 'settings.text': 'சுயவிவரம், மொழி, பண்ணை உள்ளமைவு, சென்சார் சாதனங்கள் மற்றும் தரவு ஏற்றுமதி.', 'settings.profileEyebrow': 'கணக்கு', 'settings.profile': 'சுயவிவரம்', 'settings.securityEyebrow': 'பாதுகாப்பு', 'settings.password': 'கடவுச்சொல்', 'settings.currentPassword': 'தற்போதைய கடவுச்சொல்', 'settings.newPassword': 'புதிய கடவுச்சொல் (குறைந்தது 8 எழுத்துகள்)', 'settings.changePassword': 'கடவுச்சொல்லை மாற்று', 'settings.aboutEyebrow': 'பற்றி', 'settings.about': '“Smart Farming Web System: An Autonomous AI-Agent and IoT-Driven Web Platform for Precision Agriculture and Global B2B Export Optimization” (H.A.S. Thashmila, NSBM பசுமைப் பல்கலைக்கழகம், மேற்பார்வை: திரு. கயான் பெரேரா) ஆய்வுக்கான ஆராய்ச்சிக் கலைப்பொருள்.', 'settings.disclaimer': 'பரிந்துரைகள் முடிவு ஆதரவு மட்டுமே; தொழில்முறை வேளாண் ஆலோசனைக்கு மாற்றாக இல்லை.',
